#:property AllowUnsafeBlocks=true

Span<nint> span = stackalloc nint[5];
for (int i = 0; i < span.Length; i++)
    span[i] = (nint)(i * 10);

Console.WriteLine("stackalloc Span<nint>:");
for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"  [{i}] = {span[i]}");

Span<nuint> uspan = stackalloc nuint[3];
uspan[0] = 100;
uspan[1] = 200;
uspan[2] = 300;

Console.WriteLine("stackalloc Span<nuint>:");
for (int i = 0; i < uspan.Length; i++)
    Console.WriteLine($"  [{i}] = {uspan[i]}");

Console.WriteLine($"nint size: {sizeof(nint)} bytes");

